90	function NewScript($ScriptName, $PageSecurity) {
91		/*Is page already in table */
92		$SQL = "SELECT script FROM scripts WHERE script='" . $ScriptName . "'";
93		$Result = DB_query($SQL);
94		if (DB_num_rows($Result) == 0) {
95			$SQL = "INSERT INTO `scripts` (`script`, `pagesecurity`, `description`) VALUES ('" . $ScriptName . "', '" . $PageSecurity . "', '')";
96			$Response = executeSQL($SQL, false);
97			if ($Response == 0) {
98				OutputResult(__('The script') . ' ' . $ScriptName . ' ' . __('has been inserted'), 'success');
99			} else {
100				OutputResult(__('The script') . ' ' . $ScriptName . ' ' . __('could not be inserted') . '<br />' . $SQL, 'error');
101			}
102		} else {
103			OutputResult(__('The script') . ' ' . $ScriptName . ' ' . __('already exists'), 'info');
104		}
105	}
106	
107	function RemoveScript($ScriptName) {
108		/*Is page already in table */
109		$SQL = "SELECT script FROM scripts WHERE script='" . $ScriptName . "'";
110		$Result = DB_query($SQL);
111		if (DB_num_rows($Result) != 0) {
112			$SQL = "DELETE FROM `scripts` WHERE script='" . $ScriptName . "'";
113			$Response = executeSQL($SQL, false);
114			if ($Response == 0) {
115				OutputResult(__('The script') . ' ' . $ScriptName . ' ' . __('has been removed'), 'success');
116			} else {
117				OutputResult(__('The script') . ' ' . $ScriptName . ' ' . __('could not be removed'), 'error');
118			}
119		} else {
120			OutputResult(__('The script') . ' ' . $ScriptName . ' ' . __('does not exist'), 'info');
121		}
122	}
123	
124	function NewModule($Link, $Report, $Name, $Sequence) {
125		/*Is module already in table */
126		$SQL = "SELECT modulelink FROM modules WHERE modulelink='" . $Link . "'";
127		$Result = DB_query($SQL);
128		if (DB_num_rows($Result) == 0) {
129			$SQL = "SELECT secroleid FROM securityroles";
130			$Result = DB_query($SQL);
131			while ($MyRow = DB_fetch_array($Result)) {
132				$SQL = "UPDATE `modules` SET sequence=sequence+1
133								WHERE sequence>='" . $Sequence . "'
134									AND secroleid='" . $MyRow['secroleid'] . "'";
135				$Response = executeSQL($SQL, false);
136				$SQL = "INSERT INTO `modules` ( `secroleid`,
137												`modulelink`,
138												`reportlink`,
139												`modulename`,
140												`sequence`
141											) VALUES (
142												'" . $MyRow['secroleid'] . "',
143												'" . $Link . "',
144												'" . $Report . "',
145												'" . $Name . "',
146												'" . $Sequence . "'
147											)";
148				$Response = executeSQL($SQL, false);
149				if ($Response == 0) {
150					OutputResult(__('The module') . ' ' . $Name . ' ' . __('has been inserted'), 'success');
151				} else {
152					OutputResult(__('The module') . ' ' . $Name . ' ' . __('could not be inserted') . '<br />' . $SQL, 'error');
153				}
154			}
155		} else {
156			OutputResult(__('The module') . ' ' . $Name . ' ' . __('already exists'), 'info');
157		}
158	}
159	
160	function NewMenuItem($Link, $Section, $Caption, $URL, $Sequence) {
161		/*Is module already in table */
162		$SQL = "SELECT modulelink FROM menuitems WHERE modulelink='" . $Link . "' AND menusection='" . $Section . "' AND url='" . $URL . "'";
163		$Result = DB_query($SQL);
164		if (DB_num_rows($Result) == 0) {
165			$SQL = "SELECT secroleid FROM securityroles";
166			$Result = DB_query($SQL);
167			while ($MyRow = DB_fetch_array($Result)) {
168				$SQL = "UPDATE `menuitems` SET sequence=sequence+1
169								WHERE sequence>='" . $Sequence . "'
170									AND secroleid='" . $MyRow['secroleid'] . "'
171									AND modulelink='" . $Link . "'
172									AND menusection='" . $Section . "'";
173				$Response = executeSQL($SQL, false);
174				$SQL = "INSERT INTO `menuitems` (`secroleid`,
175													`modulelink`,
176													`menusection`,
177													`caption`,
178													`url`,
179													`sequence`
180												) VALUES (
181													'" . $MyRow['secroleid'] . "',
182													'" . $Link . "',
183													'" . $Section . "',
184													'" . $Caption . "',
185													'" . $URL . "',
186													'" . $Sequence . "'
187												)";
188				$Response = executeSQL($SQL, false);
189				if ($Response == 0) {
190					OutputResult(__('The menu link') . ' ' . $Caption . ' ' . __('has been inserted'), 'success');
191				} else {
192					OutputResult(__('The menu link') . ' ' . $Caption . ' ' . __('could not be inserted') . '<br />' . $SQL, 'error');
193				}
194			}
195		} else {
196			OutputResult(__('The menu link') . ' ' . $Caption . ' ' . __('already exists'), 'info');
197		}
198	}
