200	function UpdateMenuCaption($OldCaption, $NewCaption) {
201		$SQL = "UPDATE menuitems SET caption = '" . $NewCaption . "' WHERE  caption = '" . $OldCaption . "'";
202		$Response = executeSQL($SQL, false);
203		if ($Response == 0) {
204			OutputResult(__('The menu caption') . ' ' . $OldCaption . ' ' . __('has been updated to') . ' ' . $NewCaption, 'success');
205		} else {
